// Orders and payments through PayPal's own Server SDK (@paypal/paypal-server-sdk,
// generated by APIMatic), written with APIMatic's Context Plugin for it. The
// SDK builds and checks each request from its typed models and handles the
// OAuth token; Trace keeps reading PayPal's raw JSON, so every type, error and
// retry rule downstream is unchanged. Disputes, partner onboarding and
// webhook checks, which the SDK doesn't cover, stay on the hand-written client
// this extends. test/sdk-contract.test.ts sends both clients through the same
// stub and requires the same requests and results.

import {
  ApiError,
  ArgumentsValidationError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  OrdersController,
  PaymentsController,
  PaypalExperienceUserAction,
  PaypalWalletContextShippingPreference,
  ResponseValidationError,
} from "@paypal/paypal-server-sdk";
import type { ApiResponse, OrderRequest } from "@paypal/paypal-server-sdk";
import { sum, toPayPalValue } from "@trace/core";
import { authAssertion, PayPalClient, SANDBOX_BASE, type PayPalClientOptions } from "./client.ts";
import { PayPalError, PayPalNetworkError } from "./errors.ts";
import type { Authorization, Capture, CaptureInput, CreateOrderInput, Order, Refund } from "./types.ts";

export interface PayPalSdkClientOptions extends PayPalClientOptions {
  /** Tests only: an axios adapter the SDK sends every request through (its documented seam). */
  sdkAdapter?: (config: unknown) => Promise<unknown>;
}

const REPRESENTATION = "return=representation";

export class PayPalSdkClient extends PayPalClient {
  private readonly orders: OrdersController;
  private readonly payments: PaymentsController;
  private readonly sdkOpts: PayPalSdkClientOptions;

  constructor(opts: PayPalSdkClientOptions) {
    super(opts);
    this.sdkOpts = opts;
    const base = (opts.baseUrl ?? SANDBOX_BASE).replace(/\/$/, "");
    const client = new Client({
      clientCredentialsAuthCredentials: { oAuthClientId: opts.clientId, oAuthClientSecret: opts.clientSecret },
      environment: base.includes("sandbox") ? Environment.Sandbox : Environment.Production,
      timeout: opts.timeoutMs ?? 30_000,
      // Trace retries with stored PayPal-Request-Ids itself; the SDK must not resend on its own.
      httpClientOptions: { retryConfig: { maxNumberOfRetries: 0 } },
      ...(opts.sdkAdapter ? { unstable_httpClientOptions: { adapter: opts.sdkAdapter } } : {}),
    });
    this.orders = new OrdersController(client);
    this.payments = new PaymentsController(client);
  }

  /**
   * Runs one SDK call and returns PayPal's JSON as sent. A non-2xx becomes the
   * same PayPalError the hand-written client throws; no answer at all becomes
   * PayPalNetworkError (retry with the same request ID). A 2xx the SDK's schema
   * rejects still happened at PayPal (money may have moved), so its body is used.
   */
  private async call<T>(fn: () => Promise<ApiResponse<unknown>>): Promise<T> {
    let body: unknown;
    try {
      body = (await fn()).body;
    } catch (err) {
      if (err instanceof ResponseValidationError) body = err.body;
      // Rejected before sending: a bug in the request, never worth retrying.
      else if (err instanceof ArgumentsValidationError) throw err;
      else if (err instanceof ApiError) {
        throw PayPalError.fromText(err.statusCode, "", typeof err.body === "string" ? err.body : "", err.headers?.["paypal-debug-id"]);
      } else throw new PayPalNetworkError(err);
    }
    const text = typeof body === "string" ? body : "";
    return (text ? JSON.parse(text) : undefined) as T;
  }

  private sellerAssertion(seller?: string | null): string | undefined {
    return seller ? authAssertion(this.sdkOpts.clientId, seller) : undefined;
  }

  override createOrder(input: CreateOrderInput, requestId: string): Promise<Order> {
    const total = sum(input.items.map((i) => i.priceCents));
    const money = (cents: number) => ({ currencyCode: input.currency, value: toPayPalValue(cents) });
    const body: OrderRequest = {
      intent: CheckoutPaymentIntent.Authorize,
      purchaseUnits: [
        {
          referenceId: input.invoiceId,
          invoiceId: input.invoiceId,
          customId: input.customId,
          description: input.description.slice(0, 127),
          amount: { ...money(total), breakdown: { itemTotal: money(total) } },
          ...(input.payeeMerchantId ? { payee: { merchantId: input.payeeMerchantId } } : {}),
          items: input.items.map((i) => ({ name: `${i.code} ${i.title}`.slice(0, 127), sku: i.code, quantity: "1", unitAmount: money(i.priceCents) })),
        },
      ],
      paymentSource: {
        paypal: {
          experienceContext: {
            brandName: (input.brandName ?? "Trace").slice(0, 127),
            shippingPreference: PaypalWalletContextShippingPreference.NoShipping,
            userAction: PaypalExperienceUserAction.Continue,
          },
        },
      },
    };
    return this.call<Order>(() =>
      this.orders.createOrder({ body, paypalRequestId: requestId, prefer: REPRESENTATION, paypalPartnerAttributionId: this.sdkOpts.partner?.bnCode }),
    );
  }

  override getOrder(orderId: string): Promise<Order> {
    return this.call<Order>(() => this.orders.getOrder({ id: orderId }));
  }

  override authorizeOrder(orderId: string, requestId: string): Promise<Order> {
    return this.call<Order>(() => this.orders.authorizeOrder({ id: orderId, paypalRequestId: requestId, prefer: REPRESENTATION, body: {} }));
  }

  override getAuthorization(id: string): Promise<Authorization> {
    return this.call<Authorization>(() => this.payments.getAuthorizedPayment({ authorizationId: id }));
  }

  override captureAuthorization(id: string, input: CaptureInput, requestId: string): Promise<Capture> {
    return this.call<Capture>(() =>
      this.payments.captureAuthorizedPayment({
        authorizationId: id,
        paypalRequestId: requestId,
        prefer: REPRESENTATION,
        body: {
          amount: { currencyCode: input.currency, value: toPayPalValue(input.amountCents) },
          invoiceId: input.invoiceId,
          finalCapture: input.finalCapture,
          ...(input.noteToPayer ? { noteToPayer: input.noteToPayer.slice(0, 255) } : {}),
        },
      }),
    );
  }

  override reauthorize(id: string, amount: { cents: number; currency: string } | null, requestId: string): Promise<Authorization> {
    return this.call<Authorization>(() =>
      this.payments.reauthorizePayment({
        authorizationId: id,
        paypalRequestId: requestId,
        prefer: REPRESENTATION,
        body: amount ? { amount: { currencyCode: amount.currency, value: toPayPalValue(amount.cents) } } : {},
      }),
    );
  }

  override async voidAuthorization(id: string, requestId: string): Promise<void> {
    await this.call<unknown>(() => this.payments.voidPayment({ authorizationId: id, paypalRequestId: requestId }));
  }

  override getCapture(id: string): Promise<Capture> {
    return this.call<Capture>(() => this.payments.getCapturedPayment({ captureId: id }));
  }

  override refundCapture(id: string, amount: { cents: number; currency: string } | null, requestId: string, seller?: string | null): Promise<Refund> {
    return this.call<Refund>(() =>
      this.payments.refundCapturedPayment({
        captureId: id,
        paypalRequestId: requestId,
        prefer: REPRESENTATION,
        paypalAuthAssertion: this.sellerAssertion(seller),
        body: amount ? { amount: { currencyCode: amount.currency, value: toPayPalValue(amount.cents) } } : {},
      }),
    );
  }
}

/**
 * The client the app runs: the SDK-backed one, or the hand-written one when
 * PAYPAL_HTTP=fetch (a switch back, should the SDK ever misbehave live).
 */
export function createPayPalClient(opts: PayPalClientOptions & { http?: string }): PayPalClient {
  return opts.http === "fetch" ? new PayPalClient(opts) : new PayPalSdkClient(opts);
}
